gws forms forms get --params '{"formId":"1qVAdjmDs0uNGz1pV-1Nzdb6sEHx7RxL6MQmZd1pHsks"}' 2>&1 | /opt/homebrew/bin/python3 -c "
import json,sys
raw=sys.stdin.read(); d=json.loads(raw[raw.index('{'):])
want_su={'Performance Nutrition','Applied Performance','Athletics Performance','Athletic Medicine','Athletic Mental Health Services'}
gone={'Strength & Conditioning','Sports Medicine','Sports Medicine / Athletic Training'}
for i,it in enumerate(d['items']):
    if it.get('title') in ('Sport or unit','Who uses it?'):
        vals=[o['value'] for o in it['questionItem']['question']['choiceQuestion']['options']]
        print('==',it['title'],f'({len(vals)} options)')
        for v in vals: print('   -',v)
        print('   added present:', sorted(want_su & set(vals)))
        print('   old names remaining:', sorted(gone & set(vals)) or 'NONE')
        print('   total items on form:', len(d['items']))
"

